import Foundation

// Native HTTP only: execute requests generated by Rust and return each result.
// Session/task IDs survive process termination; no Rust stack or callback pointer
// is retained across background transfers.
public final class ShareHTTP: NSObject, URLSessionDataDelegate, URLSessionTaskDelegate {
    public static let shared = ShareHTTP()
    public static let prefix = "com.whilecode.cliproam.share.upload."
    public var onChanged: (() -> Void)?
    private let queue = DispatchQueue(label: "com.whilecode.cliproam.share.http")
    private var sessions: [String: URLSession] = [:]
    private var responses: [String: Data] = [:]
    private var completions: [String: () -> Void] = [:]
    private var starting = Set<String>()
    private var active = Set<String>()
    private let maximumResponseBytes = 1024 * 1024

    private func session(_ id: String) -> URLSession {
        if let session = sessions[id] { return session }
        let configuration = URLSessionConfiguration.background(withIdentifier: Self.prefix + id)
        configuration.sharedContainerIdentifier = "group.com.whilecode.cliproam"
        configuration.isDiscretionary = false
        configuration.sessionSendsLaunchEvents = true
        let delegateQueue = OperationQueue()
        delegateQueue.maxConcurrentOperationCount = 1
        delegateQueue.underlyingQueue = queue
        let session = URLSession(configuration: configuration, delegate: self, delegateQueue: delegateQueue)
        sessions[id] = session
        return session
    }

    public func startJobs(_ result: Any, completion: @escaping (Error?) -> Void = { _ in }) {
        let jobs = (result as? [String: Any])?["jobs"] as? [String] ?? []
        guard !jobs.isEmpty else { completion(nil); return }
        let group = DispatchGroup()
        var firstError: Error?
        for id in jobs {
            group.enter()
            start(id) { error in
                if firstError == nil { firstError = error }
                group.leave()
            }
        }
        group.notify(queue: queue) { completion(firstError) }
    }

    public func start(_ id: String, completion: @escaping (Error?) -> Void) {
        queue.async {
            guard self.starting.insert(id).inserted else { completion(nil); return }
            let session = self.session(id)
            // Reconnect before generating another request, so app activation
            // never duplicates an upload still owned by the system.
            session.getAllTasks { tasks in
                self.queue.async {
                    defer { self.starting.remove(id) }
                    do {
                        if tasks.isEmpty && !self.active.contains(id) {
                            let result = try ShareCore.call(["command": "start_share", "id": id])
                            try self.submit(result, id: id)
                        }
                        completion(nil)
                    } catch {
                        self.fail(id, error)
                        completion(error)
                    }
                }
            }
        }
    }

    // The one native HTTP interface used by the shared Rust progression.
    private func submit(_ result: Any, id: String) throws {
        guard let request = (result as? [String: Any])?["request"] as? [String: Any] else {
            sessions[id]?.finishTasksAndInvalidate()
            changed()
            return
        }
        guard let address = request["url"] as? String, let url = URL(string: address),
              let body = request["bodyPath"] as? String,
              let method = request["method"] as? String,
              let callbackId = request["callbackId"] as? String else { throw ShareCore.failure("HTTP 请求结构无效") }
        var native = URLRequest(url: url)
        native.httpMethod = method
        native.timeoutInterval = 120
        for (name, value) in request["headers"] as? [String: String] ?? [:] { native.setValue(value, forHTTPHeaderField: name) }
        let task = session(id).uploadTask(with: native, fromFile: URL(fileURLWithPath: body))
        let callback = try JSONSerialization.data(withJSONObject: ["id": id, "callbackId": callbackId])
        task.taskDescription = String(decoding: callback, as: UTF8.self)
        active.insert(id)
        task.resume()
    }

    public func reconnect(_ identifier: String, completion: @escaping () -> Void) {
        queue.async {
            self.completions[identifier] = completion
            _ = self.session(String(identifier.dropFirst(Self.prefix.count)))
        }
    }

    public func urlSession(_ session: URLSession, dataTask: URLSessionDataTask, didReceive data: Data) {
        let key = "\(session.configuration.identifier ?? ""):\(dataTask.taskIdentifier)"
        if (responses[key]?.count ?? 0) + data.count <= maximumResponseBytes {
            responses[key, default: Data()].append(data)
        } else {
            responses[key] = Data(count: maximumResponseBytes + 1)
            dataTask.cancel()
        }
    }

    public func urlSession(_ session: URLSession, task: URLSessionTask, didCompleteWithError error: Error?) {
        let key = "\(session.configuration.identifier ?? ""):\(task.taskIdentifier)"
        let data = responses.removeValue(forKey: key) ?? Data()
        guard let description = task.taskDescription,
              let callback = try? JSONSerialization.jsonObject(with: Data(description.utf8)) as? [String: String],
              let id = callback["id"], let callbackId = callback["callbackId"] else { return }
        active.remove(id)
        var input: [String: Any] = ["command": "http_response", "id": id, "callbackId": callbackId]
        if data.count > maximumResponseBytes { input["error"] = "服务器响应过大" }
        else if let error = error { input["error"] = error.localizedDescription }
        else if let response = task.response as? HTTPURLResponse {
            input["status"] = response.statusCode
            input["body"] = String(decoding: data, as: UTF8.self)
        } else { input["error"] = "服务器响应缺失" }
        do {
            let next = try ShareCore.call(input)
            try submit(next, id: id)
        } catch { fail(id, error) }
    }

    public func urlSessionDidFinishEvents(forBackgroundURLSession session: URLSession) {
        finishEvents(session)
    }
    public func urlSession(_ session: URLSession, didBecomeInvalidWithError error: Error?) {
        finishEvents(session)
        if let identifier = session.configuration.identifier { sessions.removeValue(forKey: String(identifier.dropFirst(Self.prefix.count))) }
    }
    private func finishEvents(_ session: URLSession) {
        if let identifier = session.configuration.identifier, let completion = completions.removeValue(forKey: identifier) {
            DispatchQueue.main.async(execute: completion)
        }
    }
    private func fail(_ id: String, _ error: Error) {
        _ = try? ShareCore.call(["command": "error", "id": id, "error": error.localizedDescription])
        changed()
    }
    private func changed() { DispatchQueue.main.async { self.onChanged?() } }
}
